"""
dataset.py — training & evaluation datasets.

    * FoMoDataset     — pairs from the FoMo dataset (generated by
                        generate_fomo_dataset.py, or downloaded from the Hub).
                        Index schema: [{"base": "rel/path/base.png",
                                        "variants": ["rel/path/T.png", ...]}, ...]
    * PairedTransform — shared augmentation that keeps geometric correspondence
                        across the two images of a pair.
    * load_pipal / load_tid2013 / load_csiq / load_live — MOS benchmark loaders
                        returning flat (ref_path, dist_path, score) lists.
"""

import json
import math
import os
import random
from pathlib import Path

import torch
import torch.utils.data
from PIL import Image, PngImagePlugin

# PNGs with large embedded ICC profiles can exceed PIL's default decompressed
# chunk cap and raise ValueError in worker processes otherwise.
PngImagePlugin.MAX_TEXT_CHUNK = 4 * 1024 * 1024
from torch.nn.functional import pad
from torchvision import transforms


# ---------------------------------------------------------------------------
# Timestep-shift label.
#
# FLUX generates images with a resolution-dependent timestep schedule. The
# integer step stored in each variant's filename (1–50) is the denoising step
# at *generation resolution*. The training label is the FLUX-space t value:
#
#   1. Normalise:  raw_t = step / 50            (in [0, 1])
#   2. Shift to generation resolution:
#          t = apply_timestep_shift(gen_w, gen_h, raw_t)
# ---------------------------------------------------------------------------

def _shift_factor(width: int, height: int,
                  base_shift: float = 0.5, max_shift: float = 1.15) -> float:
    seq_len      = (width // 16) * (height // 16)
    base_seq_len = 256    # 16×16 patches → 256×256 px
    max_seq_len  = 4096   # 64×64 patches → 1024×1024 px
    m = (math.log(max_shift) - math.log(base_shift)) / \
        (math.log(max_seq_len) - math.log(base_seq_len))
    b = math.log(base_shift) - m * math.log(base_seq_len)
    return math.exp(m * math.log(max(seq_len, 1)) + b)


def apply_timestep_shift(width: int, height: int, timestep: float) -> torch.Tensor:
    """Shift normalised timestep [0,1] to FLUX-space t at given (width, height)."""
    shift = _shift_factor(width, height)
    t = (timestep * shift) / (1.0 + timestep * (shift - 1.0))
    return torch.tensor(t, dtype=torch.float32)


def compute_label(step: int, gen_hw: tuple[int, int]) -> torch.Tensor:
    """FLUX-space t label from an integer denoising step.

    step   : integer in [0, 50]; 0 means identity (same image).
    gen_hw : (height, width) of the image as it came out of the diffusion
             pipeline — i.e. the resize dimensions before the random crop.
             Used to apply the correct FLUX resolution shift.
    """
    if step == 0:
        return torch.tensor(0.0, dtype=torch.float32)
    gen_h, gen_w = gen_hw
    return apply_timestep_shift(gen_w, gen_h, step / 50.0)


# ---------------------------------------------------------------------------
# Shared paired-image augmentation.
#
# Applies the *same* random rotation + resize/crop to both images so geometric
# correspondence is preserved.  After cropping, images are zero-padded to
# max_crop_size and a patch-level boolean mask is returned so variable-
# resolution batches can be handled by the model.
# ---------------------------------------------------------------------------
class PairedTransform:
    def __init__(
        self,
        min_crop_size: int = 64,
        max_crop_size: int = 256,
        patch_size: int = 16,
        max_aspect_ratio: float = 2.0,
    ):
        assert min_crop_size % patch_size == 0
        assert max_crop_size % patch_size == 0
        assert min_crop_size <= max_crop_size
        self.min_crop_size   = min_crop_size
        self.max_crop_size   = max_crop_size
        self.patch_size      = patch_size
        self.max_aspect_ratio = max_aspect_ratio
        self.size_list = list(range(min_crop_size, max_crop_size + 1, patch_size))

    def _sample_target_hw(self, src_h: int, src_w: int) -> tuple[int, int]:
        max_h = min(src_h, self.max_crop_size)
        max_w = min(src_w, self.max_crop_size)
        candidates = []
        for th in self.size_list:
            if th > max_h:
                continue
            for tw in self.size_list:
                if tw > max_w:
                    continue
                aspect = max(th, tw) / max(1, min(th, tw))
                if aspect <= self.max_aspect_ratio:
                    candidates.append((th, tw))
        if not candidates:
            raise ValueError(
                f"Image ({src_h}×{src_w}) is smaller than min_crop_size={self.min_crop_size}."
            )
        return random.choice(candidates)

    def _apply(self, images: list[Image.Image], normalize_fn) -> tuple:
        """
        Returns (tensors, mask, resize_hw).

        resize_hw : (h, w) after the intermediate resize (before the crop) —
                    used as the generation resolution proxy for the label shift.
        """
        # Identical random 90° rotation for all images in the pair.
        rotation = random.choice([0, 90, 180, 270])
        if rotation:
            images = [img.rotate(rotation, expand=True) for img in images]

        src_w = min(img.size[0] for img in images)
        src_h = min(img.size[1] for img in images)

        target_h, target_w = self._sample_target_hw(src_h, src_w)

        # Resize to a random intermediate size ≥ target, capped by the source
        # so we never upscale.
        resize_h = random.randint(target_h, min(self.max_crop_size, src_h))
        resize_w = random.randint(target_w, min(self.max_crop_size, src_w))
        images = [img.resize((resize_w, resize_h), Image.Resampling.BICUBIC) for img in images]

        # Random crop down to target.
        if resize_h > target_h or resize_w > target_w:
            left = random.randint(0, resize_w - target_w)
            top  = random.randint(0, resize_h - target_h)
            images = [img.crop((left, top, left + target_w, top + target_h)) for img in images]

        tensors = [normalize_fn(img) for img in images]

        # Zero-pad to max_crop_size; mask marks real vs. padding patches.
        pad_h = self.max_crop_size - target_h
        pad_w = self.max_crop_size - target_w
        if pad_h > 0 or pad_w > 0:
            tensors = [pad(t, (0, pad_w, 0, pad_h), value=0.0) for t in tensors]

        ppside  = self.max_crop_size // self.patch_size
        real_ph = target_h // self.patch_size
        real_pw = target_w // self.patch_size
        mask = torch.zeros(ppside, ppside, dtype=torch.bool)
        mask[:real_ph, :real_pw] = True
        mask = mask.flatten()

        resize_hw = (resize_h, resize_w)
        return tensors, mask, resize_hw

    def __call__(self, img1: Image.Image, img2: Image.Image, normalize_fn=None):
        """Returns (t1, t2, mask, resize_hw)."""
        if normalize_fn is None:
            normalize_fn = transforms.ToTensor()
        tensors, mask, resize_hw = self._apply([img1, img2], normalize_fn)
        return tensors[0], tensors[1], mask, resize_hw


# ---------------------------------------------------------------------------
# FoMo dataset — pairs generated by generate_fomo_dataset.py.
#
# Index schema (JSON):
#   [{"base": "<split>/<TAG>_0000000/base.png",
#     "variants": ["<split>/<TAG>_0000000/30.png",
#                  "<split>/<TAG>_0000000/40.png"]}, ...]
#
# Pair-sampling rules (applied at __getitem__ time):
#
#   With probability 1/51 → identity pair:
#       img1 = img2 = any image from the set; label = 0.
#
#   Otherwise → pick 2 distinct images from {base} ∪ {variants}:
#       • If base is one of the two:
#             label step = timestep of the variant (its filename stem, e.g. 30).
#       • If both are variants (base not picked):
#             label step = max(t1, t2).
#
# The integer step is then converted to the FLUX-space t label via
# compute_label() using the intermediate resize dimensions as the generation
# resolution proxy (gen_hw = resize_hw from PairedTransform).
# ---------------------------------------------------------------------------
class FoMoDataset(torch.utils.data.Dataset):
    """FoMo (FLUX-generated pairs) training dataset."""

    _NORMALIZE = transforms.ToTensor()  # fixed to [0, 1]

    def __init__(
        self,
        dataroot: str,
        index_file: str,
        min_crop_size: int = 64,
        max_crop_size: int = 256,
        patch_size: int = 16,
        max_aspect_ratio: float = 2.0,
    ):
        self.dataroot = Path(dataroot)

        print(f"Loading FoMo index from {index_file}...")
        with open(index_file) as f:
            self.entries: list[dict] = json.load(f)
        if not self.entries:
            raise RuntimeError(f"Empty index file: {index_file}")

        self.transform = PairedTransform(
            min_crop_size=min_crop_size,
            max_crop_size=max_crop_size,
            patch_size=patch_size,
            max_aspect_ratio=max_aspect_ratio,
        )

    def __len__(self) -> int:
        return len(self.entries)

    @staticmethod
    def _timestep_from_path(rel_path: str) -> int:
        """Extract integer timestep from filename stem; 'base' → 0."""
        stem = Path(rel_path).stem
        if stem == 'base':
            return 0
        try:
            return int(stem)
        except ValueError:
            return 0

    def __getitem__(self, idx: int) -> dict:
        entry = self.entries[idx]
        base_rel: str = entry['base']
        variant_rels: list[str] = entry['variants']

        # Full candidate list: [(rel_path, step_int), ...]
        # base gets step=0 as a sentinel for "identity" detection.
        all_files: list[tuple[str, int]] = [(base_rel, 0)] + [
            (v, self._timestep_from_path(v)) for v in variant_rels
        ]

        # With probability 1/51 → identity pair (label 0).
        rand_draw = random.randint(0, 50)
        if rand_draw == 0 or len(all_files) < 2:
            chosen_rel, _ = random.choice(all_files)
            img = Image.open(self.dataroot / chosen_rel).convert('RGB')
            t1, t2, mask, resize_hw = self.transform(img, img, self._NORMALIZE)
            return {
                'img1':  t1,
                'img2':  t2,
                'label': torch.tensor(0.0, dtype=torch.float32),
                'mask':  mask,
            }

        # Pick 2 distinct candidates.
        a_idx, b_idx = random.sample(range(len(all_files)), 2)
        a_rel, a_step = all_files[a_idx]
        b_rel, b_step = all_files[b_idx]

        img1 = Image.open(self.dataroot / a_rel).convert('RGB')
        img2 = Image.open(self.dataroot / b_rel).convert('RGB')

        # Determine the label step:
        # • base (step=0) paired with a variant → use the variant's step.
        # • two variants (base not chosen) → max of the two steps.
        if a_step == 0:
            label_step = b_step
        elif b_step == 0:
            label_step = a_step
        else:
            label_step = max(a_step, b_step)

        t1, t2, mask, resize_hw = self.transform(img1, img2, self._NORMALIZE)
        label = compute_label(label_step, gen_hw=resize_hw)

        return {
            'img1':  t1,
            'img2':  t2,
            'label': label,
            'mask':  mask,
        }


# ---------------------------------------------------------------------------
# MOS-based evaluation datasets: PIPAL, TID2013, CSIQ, LIVE.
#
# Each returns (ref_path, dist_path, score) tuples so evaluation.py can
# iterate and call the model without knowing layout details.
#
# MOS semantics vary per benchmark:
#   PIPAL   — Elo score; higher = better quality.
#   TID2013 — MOS in [0, 9]; higher = better quality.
#   CSIQ    — DMOS in [0, 1]; higher = more distorted (worse quality).
#   LIVE    — DMOS in [0, ~100]; higher = more distorted (worse quality).
# ---------------------------------------------------------------------------

def load_pipal(root: str, split: str = 'val') -> list[tuple]:
    """
    PIPAL dataset loader.

    Handles two common on-disk layouts:
      - label directory:  <root>/{val_label,Val_Label,...}/*.txt  (one file per ref)
      - flat label file:  <root>/val_label.txt  (all refs in one file: dist_fname, elo)
    Distorted images may live in {Val_Dist, val_dist, Dist_Imgs, ...}.

    Returns list of (ref_path, dist_path, elo_score).
    """
    root = Path(root)
    cap = split.capitalize()  # 'Val' or 'Train'
    low = split.lower()

    def _find_dir(candidates):
        for c in candidates:
            p = root / c
            if p.is_dir():
                return p
        raise FileNotFoundError(f"Could not find any of {candidates} under {root}")

    ref_dir = _find_dir([f'{cap}_Ref', f'{low}_ref', f'{cap}Ref', f'{low}ref'])

    dist_candidates = [f'{cap}_Dist', f'{low}_dist', f'{cap}Dist', f'{low}dist',
                       'Dist_Imgs', 'dist_imgs']
    dist_dir = _find_dir(dist_candidates)

    # Labels: prefer a directory of per-ref txt files; fall back to a flat file.
    label_dir = None
    label_flat = None
    for c in [f'{low}_label', f'{cap}_label', f'{low}_Label', f'{cap}_Label',
              f'{low}label', f'{cap}label']:
        p = root / c
        if p.is_dir():
            label_dir = p
            break
    if label_dir is None:
        for c in [f'{low}_label.txt', f'{cap}_label.txt',
                  f'{low}_Label.txt', f'{cap}_Label.txt']:
            p = root / c
            if p.is_file():
                label_flat = p
                break

    if label_dir is None and label_flat is None:
        raise FileNotFoundError(
            f"Could not find PIPAL labels for split='{split}' under {root}"
        )

    def _resolve_ref(ref_name):
        for ext in ('.bmp', '.png', '.jpg', '.jpeg'):
            p = ref_dir / f'{ref_name}{ext}'
            if p.exists():
                return p
        return None

    samples = []

    if label_dir is not None:
        # Per-ref txt files: stem is the ref name, each line is "dist_fname,score"
        for lf in sorted(label_dir.glob('*.txt')):
            ref_path = _resolve_ref(lf.stem)
            if ref_path is None:
                continue
            with open(lf) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.rsplit(',', 1)
                    if len(parts) != 2:
                        continue
                    dist_fname, score = parts[0].strip(), parts[1].strip()
                    dist_path = dist_dir / dist_fname
                    if dist_path.exists():
                        samples.append((str(ref_path), str(dist_path), float(score)))
    else:
        # Flat file: each line is "dist_fname, score"; ref name derived from dist stem
        with open(label_flat) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = line.rsplit(',', 1)
                if len(parts) != 2:
                    continue
                dist_fname, score = parts[0].strip(), parts[1].strip()
                # PIPAL naming: A0001_10_00.bmp → ref is A0001
                ref_name = dist_fname.split('_')[0]
                ref_path = _resolve_ref(ref_name)
                if ref_path is None:
                    continue
                dist_path = dist_dir / dist_fname
                if dist_path.exists():
                    samples.append((str(ref_path), str(dist_path), float(score)))

    if not samples:
        raise RuntimeError(f"No PIPAL samples loaded from {root} (split={split})")
    return samples


def load_tid2013(root: str) -> list[tuple]:
    """
    TID2013 dataset loader.

    Layout:
        <root>/reference_images/  — reference images
        <root>/distorted_images/  — distorted images
        <root>/mos_with_names.txt — lines: <mos_score> <distorted_filename>

    MOS in [0, 9]; higher = better quality.
    Returns list of (ref_path, dist_path, mos).
    """
    root = Path(root)
    mos_file     = root / 'mos_with_names.txt'
    dist_dir     = root / 'distorted_images'
    ref_dir      = root / 'reference_images'

    if not mos_file.exists():
        raise FileNotFoundError(f"TID2013 mos_with_names.txt not found: {mos_file}")

    # The official release mixes filename cases (I01.BMP … I24.BMP, i25.bmp,
    # and both in mos_with_names.txt), so names are matched case-insensitively.
    ref_by_stem  = {p.stem.lower(): p for p in ref_dir.iterdir()  if p.is_file()}
    dist_by_name = {p.name.lower(): p for p in dist_dir.iterdir() if p.is_file()}

    samples = []
    with open(mos_file) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 2:
                continue
            mos, dist_fname = float(parts[0]), parts[1]
            dist_path = dist_by_name.get(dist_fname.lower())
            if dist_path is None:
                continue
            # Reference stem is the first part of the distorted filename before '_'.
            # e.g. 'I01_01_1.bmp' → ref 'I01'
            ref_path = ref_by_stem.get(dist_fname.split('_')[0].lower())
            if ref_path is None:
                continue
            samples.append((str(ref_path), str(dist_path), mos))

    if len(samples) < 3000:
        raise RuntimeError(
            f"TID2013: loaded only {len(samples)} of the 3000 rated images from "
            f"{root} — check the reference_images / distorted_images filenames.")
    return samples


def load_csiq(root: str) -> list[tuple]:
    """
    CSIQ dataset loader.

    Layout:
        <root>/src_imgs/    — reference images
        <root>/dst_imgs/    — distorted images organised in sub-folders by type
        <root>/csiq.DMOS.xlsx — DMOS scores

    DMOS in [0, 1]; higher = more distorted.
    Returns list of (ref_path, dist_path, dmos).

    Reads the xlsx without pandas — uses Python's zipfile + xml.etree.
    """
    import zipfile
    import xml.etree.ElementTree as ET

    root = Path(root)
    src_dir  = root / 'src_imgs'
    dst_dir  = root / 'dst_imgs'
    xlsx     = root / 'csiq.DMOS.xlsx'

    for p, name in [(src_dir, 'src_imgs'), (dst_dir, 'dst_imgs'), (xlsx, 'csiq.DMOS.xlsx')]:
        if not p.exists():
            raise FileNotFoundError(f"CSIQ {name} not found: {p}")

    # Parse xlsx manually: extract shared strings + the DMOS sheet.
    with zipfile.ZipFile(str(xlsx)) as zf:
        # Shared strings table
        shared = []
        if 'xl/sharedStrings.xml' in zf.namelist():
            with zf.open('xl/sharedStrings.xml') as sf:
                tree = ET.parse(sf)
                for si in tree.getroot():
                    t = si.find('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')
                    shared.append(t.text if t is not None else '')

        def _cell_value(c, shared):
            t_attr = c.get('t', '')
            v = c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
            if v is None:
                return None
            if t_attr == 's':
                return shared[int(v.text)]
            return v.text

        # Find the sheet with 'dmos' and 'dst_type' headers.
        ns = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
        records = []
        for sheet_file in zf.namelist():
            if not sheet_file.startswith('xl/worksheets/sheet'):
                continue
            with zf.open(sheet_file) as wf:
                rows = list(ET.parse(wf).getroot().iter(f'{ns}row'))
            if not rows:
                continue
            # Read header row — map column name → absolute column index from cell ref
            def _col_idx_from_ref(r):
                col_letter = ''.join(ch for ch in r if ch.isalpha())
                return sum((ord(ch) - ord('A') + 1) * (26 ** i)
                           for i, ch in enumerate(reversed(col_letter))) - 1

            header_cells = list(rows[0].iter(f'{ns}c'))
            header_lower = [str(_cell_value(c, shared)).lower() if _cell_value(c, shared) else ''
                            for c in header_cells]
            if 'dmos' not in header_lower or 'dst_type' not in header_lower:
                continue
            col = {}
            for c in header_cells:
                val = _cell_value(c, shared)
                if val:
                    col[str(val).lower()] = _col_idx_from_ref(c.get('r', ''))
            for row in rows[1:]:
                cells = list(row.iter(f'{ns}c'))
                # cells may be sparse; use 'r' attribute for column index
                row_map = {}
                for c in cells:
                    row_map[_col_idx_from_ref(c.get('r', ''))] = _cell_value(c, shared)
                try:
                    image    = row_map.get(col.get('image', -1))
                    dst_type = row_map.get(col.get('dst_type', -1))
                    dst_lev  = row_map.get(col.get('dst_lev', -1))
                    dmos_val = row_map.get(col.get('dmos', -1))
                    if None in (image, dst_type, dst_lev, dmos_val):
                        continue
                    records.append({
                        'image': str(image), 'dst_type': str(dst_type),
                        'dst_lev': str(dst_lev), 'dmos': float(dmos_val),
                    })
                except (TypeError, ValueError):
                    continue
            break  # found the right sheet

    if not records:
        raise RuntimeError(f"Could not parse DMOS records from {xlsx}")

    # Map CSIQ distortion type names to folder names.
    _TYPE_TO_DIR = {
        'jpeg':       'jpeg',
        'jpeg 2000':  'jpeg2000',
        'jpeg2000':   'jpeg2000',
        'awgn':       'awgn',
        'noise':      'awgn',   # csiq.DMOS.xlsx labels AWGN as 'noise'
        'blur':       'blur',
        'contrast':   'contrast',
        'fnoise':     'fnoise',
        'pink noise': 'fnoise',
    }

    samples = []
    for rec in records:
        stem = rec['image']
        ref_path = next(
            (src_dir / f'{stem}{ext}' for ext in ('.png', '.bmp', '.jpg')
             if (src_dir / f'{stem}{ext}').exists()),
            None,
        )
        if ref_path is None:
            continue

        folder = _TYPE_TO_DIR.get(rec['dst_type'].lower())
        if folder is None:
            continue
        dist_subdir = dst_dir / folder
        if not dist_subdir.is_dir():
            continue

        level = rec['dst_lev']
        dist_path = None
        for ext in ('.png', '.bmp', '.jpg'):
            for type_case in (folder.upper(), folder, folder.capitalize()):
                p = dist_subdir / f'{stem}.{type_case}.{level}{ext}'
                if p.exists():
                    dist_path = p
                    break
            if dist_path:
                break
        if dist_path is None:
            # Case-insensitive fallback
            target = f'{stem.lower()}.{folder.lower()}.{level}'
            dist_path = next(
                (p for p in dist_subdir.iterdir() if p.stem.lower() == target), None
            )
        if dist_path is None:
            continue

        samples.append((str(ref_path), str(dist_path), rec['dmos']))

    if not samples:
        raise RuntimeError(f"No CSIQ samples loaded from {root}")
    return samples


def load_live(root: str) -> list[tuple]:
    """
    LIVE IQA dataset loader.

    Layout:
        <root>/refimgs/       — reference images
        <root>/{jp2k,jpeg,wn,gblur,fastfading}/  — distorted images
        <root>/dmos_realigned.mat (or dmos.mat)
        <root>/refnames_all.mat

    DMOS in [0, ~100]; higher = more distorted.
    Returns list of (ref_path, dist_path, dmos).
    """
    from scipy.io import loadmat

    root = Path(root)
    ref_dir = root / 'refimgs'
    if not ref_dir.is_dir():
        raise FileNotFoundError(f"LIVE refimgs not found: {ref_dir}")

    # Load DMOS and reference names from .mat files.
    dmos_path = root / 'dmos_realigned.mat'
    if not dmos_path.exists():
        dmos_path = root / 'dmos.mat'
    if not dmos_path.exists():
        raise FileNotFoundError(f"LIVE dmos .mat file not found under {root}")

    refnames_path = root / 'refnames_all.mat'
    if not refnames_path.exists():
        raise FileNotFoundError(f"LIVE refnames_all.mat not found: {refnames_path}")

    def _vec(mat, keys):
        for k in keys:
            if k in mat:
                v = mat[k].flatten()
                return v
        return None

    dmos_mat = loadmat(str(dmos_path))
    dmos     = _vec(dmos_mat, ['dmos_new', 'dmos', 'DMOS'])
    orgs     = _vec(dmos_mat, ['orgs', 'isorgs'])

    refnames_mat = loadmat(str(refnames_path))
    raw_ref = _vec(refnames_mat, ['refnames_all', 'refnames'])
    refnames = [str(r[0]) if hasattr(r, '__len__') else str(r) for r in raw_ref]

    # Drop original (un-distorted) entries (orgs flag == 1).
    keep = list(range(len(dmos)))
    if orgs is not None and len(orgs) == len(dmos):
        keep = [i for i, v in enumerate(orgs) if int(v) == 0]

    dmos_kept    = [float(dmos[i])     for i in keep]
    refnames_kept = [refnames[i]        for i in keep if i < len(refnames)]

    # Collect distorted images in canonical order, then apply same keep filter.
    _DIST_DIRS = ['jp2k', 'jpeg', 'wn', 'gblur', 'fastfading']
    _IMG_EXTS  = {'.bmp', '.png', '.jpg', '.jpeg'}

    def _natural_key(s):
        import re
        return [int(c) if c.isdigit() else c for c in re.split(r'(\d+)', s)]

    dist_paths_all = []
    for dname in _DIST_DIRS:
        ddir = root / dname
        if not ddir.is_dir():
            continue
        files = sorted(
            [p for p in ddir.iterdir() if p.suffix.lower() in _IMG_EXTS],
            key=lambda p: _natural_key(p.name),
        )
        dist_paths_all.extend(files)

    if not dist_paths_all:
        raise FileNotFoundError(f"No distorted images found under {root}")

    dist_kept = [dist_paths_all[i] for i in keep if i < len(dist_paths_all)]

    if len(refnames_kept) != len(dmos_kept) or len(dist_kept) != len(dmos_kept):
        raise ValueError("LIVE metadata length mismatch after filtering originals.")

    samples = []
    for mos, ref_name, dist_path in zip(dmos_kept, refnames_kept, dist_kept):
        ref_filename = Path(ref_name).name
        ref_path = ref_dir / ref_filename
        if not ref_path.exists():
            target = ref_filename.lower()
            ref_path = next(
                (p for p in ref_dir.iterdir() if p.name.lower() == target), None
            )
        if ref_path is None:
            raise FileNotFoundError(f"LIVE reference image not found: {ref_name}")
        samples.append((str(ref_path), str(dist_path), mos))

    if not samples:
        raise RuntimeError(f"No LIVE samples loaded from {root}")
    return samples
